import java.util.Map;

@RestControllerAdvice
public class WebExceptionHandler {

    @ExceptionHandler(BookAlreadyOnLoanException.class)
    public ProblemDetail handleAlreadyOnLoan(BookAlreadyOnLoanException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }

    @ExceptionHandler(BookDiscardedException.class)
    public ResponseEntity<Map<String, String>> handleBookDiscarded(BookDiscardedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "BOOK_DISCARDED"));
    }

    @ExceptionHandler(CannotDiscardBookOnLoanException.class)
    public ResponseEntity<Map<String, String>> handleCannotDiscardOnLoan(CannotDiscardBookOnLoanException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "BOOK_ON_LOAN"));
    }

    @ExceptionHandler(BookAvailableException.class)
    public ResponseEntity<Map<String, String>> handleBookAvailable(BookAvailableException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "BOOK_AVAILABLE"));
    }

    @ExceptionHandler(ReservedForOtherException.class)
    public ResponseEntity<Map<String, String>> handleReservedForOther(ReservedForOtherException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "RESERVED_FOR_OTHER"));
    }

    @ExceptionHandler(AlreadyReservedException.class)
    public ResponseEntity<Map<String, String>> handleAlreadyReserved(AlreadyReservedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "ALREADY_RESERVED"));
    }

    @ExceptionHandler(CreditRejectedException.class)
    public ResponseEntity<Map<String, String>> handleCreditRejected(CreditRejectedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "CREDIT_REJECTED"));
    }

    @ExceptionHandler(CreditCheckUnavailableException.class)
    public ResponseEntity<Map<String, String>> handleCreditCheckUnavailable(CreditCheckUnavailableException e) {
        return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body(Map.of("error", "CREDIT_CHECK_UNAVAILABLE"));
    }

    @ExceptionHandler(LoanLimitExceededException.class)
    public ResponseEntity<Map<String, String>> handleLoanLimitExceeded(LoanLimitExceededException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "LOAN_LIMIT_EXCEEDED"));
    }

    @ExceptionHandler(LoanAlreadyReturnedException.class)
    public ResponseEntity<Map<String, String>> handleAlreadyReturned(LoanAlreadyReturnedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "ALREADY_RETURNED"));
    }

    @ExceptionHandler(LoanNotFoundException.class)
    public ProblemDetail handleLoanNotFound(LoanNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(BookNotFoundException.class)
    public ProblemDetail handleNotFound(BookNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(MemberNotFoundException.class)
    public ProblemDetail handleMemberNotFound(MemberNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ProblemDetail handleInvalidInput(IllegalArgumentException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, e.getMessage());
    }
}

